     3	
     4	export function shouldContinueToolLoop(
     5	  stopReason: string,
     6	  pendingToolCalls: ToolCall[],
     7	  toolRegistry: ToolRegistry | undefined
     8	): boolean {
     9	  return stopReason === 'tool_use' && pendingToolCalls.length > 0 && toolRegistry !== undefined;
    10	}
    11	
    12	export async function collectText(stream: AsyncGenerator<MessageChunk>): Promise<string> {
    13	  let text = '';
    14	  for await (const chunk of stream) {
    15	    if (chunk.type === 'text') text += chunk.text;
    16	  }
    17	  return text;
    18	}
    19	
    20	export function buildToolCallMessages(pendingToolCalls: ToolCall[]): Message {
    21	  return {
    22	    role: 'assistant',
    23	    content: pendingToolCalls.map(tc => ({
    24	      type: 'tool_use' as const,
    25	      toolUseId: tc.id,
    26	      name: tc.name,
    27	      input: tc.input,
    28	    })),
    29	  };
    30	}
    31	
    32	export function collectToolCalls(chunk: MessageChunk, pendingToolCalls: ToolCall[]): void {
    33	  if (chunk.type === 'tool_use') pendingToolCalls.push(chunk.toolCall);
    34	}
    35	
    36	export function extractStopReason(chunk: MessageChunk): string | null {
    37	  return chunk.type === 'stop' ? chunk.stopReason : null;
    38	}
    39	
    40	export function extractUsage(chunk: MessageChunk): UsageMetadata | undefined {
    41	  return chunk.type === 'stop' ? chunk.usage : undefined;
    42	}
    43	
    44	export function accumulateUsage(
    45	  accumulated: UsageMetadata | undefined,
    46	  next: UsageMetadata | undefined
    47	): UsageMetadata | undefined {
    48	  if (accumulated === undefined) return next;
    49	  if (next === undefined) return accumulated;
    50	  return {
    51	    inputTokens: accumulated.inputTokens + next.inputTokens,
    52	    outputTokens: accumulated.outputTokens + next.outputTokens,
    53	    totalTokens: accumulated.totalTokens + next.totalTokens,
    54	  };
    55	}
